import{_ as a,o as t,c as o,a0 as n}from"./chunks/framework.CBux2OW7.js";const u=JSON.parse('{"title":"Feature to PR Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/feature-to-pr.md","filePath":"workflows/feature-to-pr.md"}'),r={name:"workflows/feature-to-pr.md"};function i(s,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="feature-to-pr-workflow" tabindex="-1">Feature to PR Workflow <a class="header-anchor" href="#feature-to-pr-workflow" aria-label="Permalink to &quot;Feature to PR Workflow&quot;">​</a></h1><p>When an AI Agent or developer is tasked with adding a new feature to TechyNews, they must follow this rigorous standard operating procedure to maintain codebase stability.</p><h2 id="phase-1-planning" tabindex="-1">Phase 1: Planning <a class="header-anchor" href="#phase-1-planning" aria-label="Permalink to &quot;Phase 1: Planning&quot;">​</a></h2><ol><li><strong>Understand Context:</strong> Read the relevant Model and Service documentation.</li><li><strong>Design Document:</strong> Create a markdown file in <code>ai-specs/changes/FEATURE-NAME.md</code> outlining the proposed database migrations, controller changes, and React component updates.</li><li><strong>Approval:</strong> Await user/senior developer approval on the plan.</li></ol><h2 id="phase-2-implementation-isolated" tabindex="-1">Phase 2: Implementation (Isolated) <a class="header-anchor" href="#phase-2-implementation-isolated" aria-label="Permalink to &quot;Phase 2: Implementation (Isolated)&quot;">​</a></h2><ol><li><strong>Branching:</strong> Work MUST be done on a separate git branch (or a shared worktree for agents). NEVER commit directly to <code>main</code>.</li><li><strong>Backend First:</strong> Create migrations (<code>php artisan make:migration</code>), models, and controllers. Run <code>php artisan test</code> continuously.</li><li><strong>Frontend Integration:</strong> Update Inertia views and components. Ensure Tailwind classes adhere to the <code>Theme System</code> rules (always include <code>dark:</code> variants).</li></ol><h2 id="phase-3-qa-verification" tabindex="-1">Phase 3: QA &amp; Verification <a class="header-anchor" href="#phase-3-qa-verification" aria-label="Permalink to &quot;Phase 3: QA &amp; Verification&quot;">​</a></h2><ol><li><strong>Build Step:</strong> You MUST run <code>npm run build</code> and ensure it completes with 0 errors. A Vite compilation failure means the PR is invalid.</li><li><strong>E2E Testing:</strong> Run <code>npx playwright test</code>.</li><li><strong>Linting:</strong> Ensure PHP follows PSR-12 and React follows standard ESLint rules.</li></ol><h2 id="phase-4-pull-request" tabindex="-1">Phase 4: Pull Request <a class="header-anchor" href="#phase-4-pull-request" aria-label="Permalink to &quot;Phase 4: Pull Request&quot;">​</a></h2><ol><li>Use the <code>techy-pr-builder</code> skill (if operating as an agent) to generate a standardized PR description.</li><li>Include screenshots of any UI changes.</li><li>Submit the PR for review. Merging to <code>main</code> will automatically trigger the GitHub Actions deployment pipeline.</li></ol>',10)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
